const script = `
$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='dsh-check';'Accept'='application/vnd.github+json'}
try {
  $r = Invoke-RestMethod -Uri 'https://api.github.com/search/repositories?q=topic:dsh-plugin&sort=stars&order=desc&per_page=40' -Headers $h -TimeoutSec 40
  foreach ($i in $r.items) { "$($i.stargazers_count)|$($i.full_name)|$($i.description)" }
} catch { "ERR: $($_.Exception.Message)" }
`;
const r = await tools.pwsh({ command: script, description: "Query GitHub for dsh-plugin repos" });
console.log(r.kind === "foreground" ? r.stdout.text + r.stderr.text : JSON.stringify(r).slice(0,500));
